package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.impl.rocksdb.ReplicatedRangeStore;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.ratis.client.RaftClient;
import org.apache.ratis.protocol.Message;
import org.apache.ratis.thirdparty.com.google.protobuf.ByteString;

/** Fresh committed permission to bootstrap one fenced relocation LISTENER; grants no configuration change. */
public final class RatisTopologyJoinAuthority {
    public static final int KIND=100,REQUEST_BYTES=ScopedTransactionRpc.HEADER_BYTES+113;
    public static final int MAX_REPLY_BYTES=ScopedTransactionRpc.HEADER_BYTES+40+TopologyChange.MAX_DEFINITION_BYTES+TopologyChange.MAX_STATUS_BYTES;
    private RatisTopologyJoinAuthority() {}
    public enum Purpose { REGISTER, CONFIGURATION, PUBLICATION }
    public record Request(UUID cluster,UUID database,UUID domain,UUID intent,byte[] digest,UUID receiver,Purpose purpose) {
        public Request { Objects.requireNonNull(cluster);Objects.requireNonNull(database);Objects.requireNonNull(domain);Objects.requireNonNull(intent);Objects.requireNonNull(receiver);Objects.requireNonNull(purpose);if(digest==null || digest.length!=32)throw new IllegalArgumentException("Invalid join definition digest");digest=digest.clone(); }
        @Override public byte[] digest(){return digest.clone();}
        public static Request of(TopologyChange.Definition definition,UUID receiver){var h=definition.header();return new Request(h.clusterId(),h.databaseId(),h.domainId(),h.intentId(),h.definitionDigest(),receiver,Purpose.REGISTER);}
        public static Request of(TopologyChange.Header header,UUID actor,Purpose purpose){return new Request(header.clusterId(),header.databaseId(),header.domainId(),header.intentId(),header.definitionDigest(),actor,purpose);}
    }
    public record View(UUID catalogue,ApplyPosition cut,TopologyChange.Definition definition,TopologyChange.State state) {
        public View { Objects.requireNonNull(catalogue);Objects.requireNonNull(cut);Objects.requireNonNull(definition);Objects.requireNonNull(state);state.requireDefinition(definition);if(cut.term()<1 || cut.index()<1 || definition.kind()!=TopologyChange.Kind.RELOCATE || state.phase()!=TopologyChange.Phase.PREPARED && state.phase()!=TopologyChange.Phase.JOINING && state.phase()!=TopologyChange.Phase.RECONFIGURED && state.phase()!=TopologyChange.Phase.ACTIVE)throw new IllegalArgumentException("Join requires committed PREPARED relocation"); }
        public ReplicaDescriptor require(Request request){var h=definition.header();if(!request.cluster().equals(h.clusterId()) || !request.database().equals(h.databaseId()) || !request.domain().equals(h.domainId()) || !request.intent().equals(h.intentId()) || !Arrays.equals(request.digest(),h.definitionDigest()))throw new IllegalArgumentException("Join authority identity differs");var receiver=definition.targets().getFirst().replicas().stream().filter(r->r.replicaId().equals(request.receiver())).findFirst().orElseThrow(()->new IllegalArgumentException("Join receiver missing"));if(request.purpose()==Purpose.REGISTER && (receiver.role()!=ReplicaDescriptor.Role.LISTENER || definition.parents().getFirst().replicas().stream().anyMatch(r->r.replicaId().equals(receiver.replicaId()))))throw new IllegalArgumentException("Join receiver is not a newly staged LISTENER");if(request.purpose()==Purpose.CONFIGURATION && state.phase()!=TopologyChange.Phase.JOINING && state.phase()!=TopologyChange.Phase.RECONFIGURED || request.purpose()==Purpose.PUBLICATION && state.phase()!=TopologyChange.Phase.ACTIVE)throw new IllegalArgumentException("Relocation authority phase differs from purpose");return receiver;}
    }
    public static final class Client {
        private final RaftClient client;private final UUID cluster,database,catalogue;
        public Client(RaftClient borrowed,UUID cluster,UUID database,UUID catalogue){client=Objects.requireNonNull(borrowed);this.cluster=Objects.requireNonNull(cluster);this.database=Objects.requireNonNull(database);this.catalogue=Objects.requireNonNull(catalogue);if(!client.getGroupId().getUuid().equals(catalogue))throw new IllegalArgumentException("Join catalogue group differs");}
        public View read(Request request)throws IOException {if(!cluster.equals(request.cluster()) || !database.equals(request.database()))throw new IllegalArgumentException("Join namespace differs");var reply=RatisRoutedClient.rpc(()->client.io().sendReadOnly(Message.valueOf(ByteString.copyFrom(request(request)))));if(reply==null || !reply.isSuccess() || reply.getMessage()==null || reply.getRaftGroupId()==null || !reply.getRaftGroupId().getUuid().equals(catalogue) || reply.getMessage().getContent().size()>MAX_REPLY_BYTES)throw new IOException("Join authority read failed",reply==null?null:reply.getException());try{return decodeReply(reply.getMessage().getContent().toByteArray(),request,catalogue);}catch(IllegalArgumentException invalid){throw new IOException("Invalid join authority reply",invalid);}}
    }
    public static byte[] request(Request request){var out=ByteBuffer.allocate(113);for(var id:List.of(request.cluster(),request.database(),request.domain(),request.intent()))ScopedTransactionRpc.uuid(out,id);out.put(request.digest());ScopedTransactionRpc.uuid(out,request.receiver());out.put((byte)request.purpose().ordinal());return ScopedTransactionRpc.frame(KIND,out.array());}
    public static Request decodeRequest(byte[] bytes){var packet=ScopedTransactionRpc.parse(bytes,REQUEST_BYTES);if(packet.kind()!=KIND || packet.body().length!=113)throw new IllegalArgumentException("Invalid join authority request");var in=ByteBuffer.wrap(packet.body());var cluster=ScopedTransactionRpc.uuid(in);var database=ScopedTransactionRpc.uuid(in);var domain=ScopedTransactionRpc.uuid(in);var intent=ScopedTransactionRpc.uuid(in);byte[] digest=new byte[32];in.get(digest);var receiver=ScopedTransactionRpc.uuid(in);int purpose=in.get()&255;if(purpose>=Purpose.values().length)throw new IllegalArgumentException("Invalid relocation purpose");return new Request(cluster,database,domain,intent,digest,receiver,Purpose.values()[purpose]);}
    public static View readNative(ReplicatedRangeStore store,UUID column,UUID cluster,UUID database,Request request)throws IOException {
        if(!cluster.equals(request.cluster()) || !database.equals(request.database()))throw new IOException("Join namespace differs");try{var key=ByteBuffer.allocate(16);ScopedTransactionRpc.uuid(key,request.domain());var points=store.readSchemaAuthorityPoints(List.of(new ReplicatedRangeStore.PhysicalPoint(column,RatisTopologyCatalogue.headKey(request.domain())),new ReplicatedRangeStore.PhysicalPoint(column,RatisTopologyCatalogue.stateKey(request.intent())),new ReplicatedRangeStore.PhysicalPoint(column,RatisTopologyCatalogue.definitionKey(request.digest())),new ReplicatedRangeStore.PhysicalPoint(column,key.array())),new int[]{TopologyChange.MAX_STATUS_BYTES,TopologyChange.MAX_STATUS_BYTES,TopologyChange.MAX_DEFINITION_BYTES,RatisCatalogue.MAX_DIRECTORY_BYTES});var values=points.values();if(points.position()==null || values.stream().anyMatch(Objects::isNull) || !Arrays.equals(values.get(0),values.get(1)))throw new IOException("Join head/intent inconsistent");var definition=TopologyChange.Definition.decode(values.get(2));var view=new View(store.ownership().owner().groupId(),points.position(),definition,TopologyChange.State.decode(values.get(1)));view.require(request);if(!Arrays.equals(values.get(3),RangeDirectoryCodec.encode(view.state().phase()==TopologyChange.Phase.ACTIVE?definition.targetDirectory():definition.sourceDirectory())))throw new IOException("Join source directory changed");return view;}catch(org.rocksdb.RocksDBException|IllegalArgumentException|IllegalStateException invalid){throw new IOException("Invalid native join authority",invalid);}
    }
    public static byte[] reply(View view){var definition=view.definition().encode();var state=view.state().encode();var out=ByteBuffer.allocate(40+definition.length+state.length);ScopedTransactionRpc.uuid(out,view.catalogue());out.putLong(view.cut().term()).putLong(view.cut().index());ScopedTransactionRpc.putBlob(out,definition);ScopedTransactionRpc.putBlob(out,state);return ScopedTransactionRpc.frame(KIND,out.array());}
    public static View decodeReply(byte[] bytes,Request request,UUID catalogue){var packet=ScopedTransactionRpc.parse(bytes,MAX_REPLY_BYTES);if(packet.kind()!=KIND || packet.body().length<40)throw new IllegalArgumentException("Invalid join reply");var in=ByteBuffer.wrap(packet.body());var group=ScopedTransactionRpc.uuid(in);var cut=new ApplyPosition(in.getLong(),in.getLong());var definition=TopologyChange.Definition.decode(ScopedTransactionRpc.blob(in,TopologyChange.MAX_DEFINITION_BYTES,false));var state=TopologyChange.State.decode(ScopedTransactionRpc.blob(in,TopologyChange.MAX_STATUS_BYTES,false));if(in.hasRemaining() || !group.equals(catalogue))throw new IllegalArgumentException("Join reply group/tail differs");var view=new View(group,cut,definition,state);view.require(request);return view;}
}
